/**
 * US state outline icons (50 states + DC).
 *
 * Paths are simplified silhouettes from @svg-maps/usa (amCharts-derived),
 * each normalized into a shared viewBox of "0 0 100 100" so icons look
 * consistent at 24×24 / 48×48 or in grids. Geographic accuracy is secondary
 * to recognizable silhouettes and visual balance.
 *
 * Invalid abbreviations render a simple map-pin fallback (not null) so UI
 * does not blank awkwardly.
 *
 * @example
 * <StateIcon state="TX" className="size-6 text-foreground" />
 * <StateIcon state="ca" size={48} className="fill-none stroke-current stroke-2" />
 */

