const STATE_CODES = Object.keys(STATE_ICONS) as StateCode[];

export function isStateCode(value: string): value is StateCode {
  return Object.prototype.hasOwnProperty.call(STATE_ICONS, value.toUpperCase());
}

export function getStateIcon(code: string): StateIconEntry | undefined {
  const key = code.trim().toUpperCase();
  if (!isStateCode(key)) return undefined;
  return STATE_ICONS[key];
}

export function listStateIcons(): Array<{ code: StateCode } & StateIconEntry> {
  return STATE_CODES.map((code) => ({ code, ...STATE_ICONS[code] }));
}

export type StateIconProps = {
  /** Two-letter USPS abbreviation (case-insensitive). */
  state: string;
  className?: string;
  /** Default width/height when not sized via className. */
  size?: number | string;
} & Omit<SVGProps<SVGSVGElement>, "viewBox" | "children" | "width" | "height">;

function MapPinFallback({
  className,
  size = 24,
  ...rest
}: Omit<StateIconProps, "state">) {
  return (
    <svg
      viewBox={DEFAULT_STATE_ICON_VIEWBOX}
      width={size}
      height={size}
      className={className}
      fill="currentColor"
      role="img"
      aria-label="Unknown location"
      {...rest}
    >
      <path d={MAP_PIN_FALLBACK_PATH} />
    </svg>
  );
}

/**
 * Renders a normalized US state outline icon.
 * Unknown codes → map-pin fallback (keeps layout from collapsing).
 */
export function StateIcon({
  state,
  className,
  size = 24,
  ...rest
}: StateIconProps) {
  const entry = getStateIcon(state);
  if (!entry) {
    return <MapPinFallback className={className} size={size} {...rest} />;
  }

  return (
    <svg
      viewBox={entry.viewBox ?? DEFAULT_STATE_ICON_VIEWBOX}
      width={size}
      height={size}
      className={className}
      fill="currentColor"
      role="img"
      aria-label={entry.name}
      {...rest}
    >
      <path d={entry.path} />
    </svg>
  );
}
